DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261027202359_AddUserAuthentication') THEN
    ALTER TABLE "Users" ADD "NormalizedEmail" character varying(254) NOT NULL DEFAULT '';
